What happens when outer() is called?
function outer() {
  function inner() { const secret = 1; }
  inner();
  console.log(secret);
}

What does this code log?
function make() {
  let msg = 'a';
  const log = () => console.log(msg);
  msg = 'b';
  return log;
}
make()();

What does this code log?
let x = 'global';
function show() { console.log(x); }
function run() { let x = 'local'; show(); }
run();
